// The GDs of every Picking in this call (digits only: interpolated into sql_node_GdBusy).
const items = {{workflowparams:arrayData}};
const ids = new Set();
for (const item of Array.isArray(items) ? items : []) {
  for (const id of Array.isArray(item && item.gd_no) ? item.gd_no : []) {
    if (/^[0-9]{1,20}$/.test(String(id))) ids.add(String(id));
  }
}
return { gdIdSql: ids.size > 0 ? [...ids].join(",") : "0" };

// A Goods Delivery these Pickings name is being saved in the background (GD Edit V2 / GD Completed V2): refuse them all.
const raw = {{node:sql_node_GdBusy.data}};
const row = (Array.isArray(raw) ? raw : raw ? [raw] : []).filter((r) => r && r.gd_no)[0];
return row
  ? { busy: 1, message: "Goods Delivery " + row.gd_no + " is being saved in the background. Wait a moment, then try again." }
  : { busy: 0, message: "" };

// The GD lines this call puts on a live Picking (an Add, or a Draft saved as Created / Completed) and how much of each:
// sql_node_Cover reads what other live Pickings already hold of them. Confirms of a live Picking (mobile, the form) are
// not checked and read nothing. Digits only: the ids are interpolated into sql_node_Cover.
const items = {{workflowparams:arrayData}};
const saveAs = {{workflowparams:saveAs}};
const pageStatus = {{workflowparams:pageStatus}};
const q8 = (v) => Number((parseFloat(v) || 0).toFixed(8));
const digits = (v) => (/^[0-9]{1,20}$/.test(String(v === undefined || v === null ? "" : v)) ? String(v) : "");
const mine = {};
const gds = new Set();
const own = new Set();
if (saveAs !== "Draft" && saveAs !== "Cancelled") {
  for (const p of Array.isArray(items) ? items : []) {
    if (!p || (pageStatus !== "Add" && p.to_status !== "Draft")) continue;
    if (digits(p.id)) own.add(digits(p.id));
    for (const id of Array.isArray(p.gd_no) ? p.gd_no : []) if (digits(id)) gds.add(digits(id));
    const rows = [];
    for (const r of Array.isArray(p.table_picking_items) ? p.table_picking_items : []) {
      if (!r) continue;
      rows.push(r);
      for (const c of Array.isArray(r.children) ? r.children : []) if (c) rows.push(c);
    }
    for (const r of rows) {
      const line = digits(r.gd_line_id);
      if (!line || r.row_type === "header" || r.line_status === "Cancelled") continue;
      if (digits(r.gd_id)) gds.add(digits(r.gd_id));
      mine[line] = q8((mine[line] || 0) + q8(r.qty_to_pick));
    }
  }
}
for (const line of Object.keys(mine)) if (!(mine[line] > 0)) delete mine[line];
const lines = Object.keys(mine);
return {
  check: lines.length > 0 && gds.size > 0 ? 1 : 0,
  lineIdCsv: lines.length ? lines.join(",") : "0",
  gdIdCsv: gds.size ? [...gds].join(",") : "0",
  ownIdCsv: own.size ? [...own].join(",") : "0",
  mine,
};

// A GD line may not be on Pickings for more than its quantity: what other live Pickings already hold (sql_node_Cover:
// open ones their qty_to_pick, Completed ones what they picked, as Convert to Picking counts it) + what this call adds.
// Over -> the whole call is refused before any Picking is written.
const raw = {{node:sql_node_Cover.data}};
const mine = {{node:code_node_CoverIds.data.mine}} || {};
const EPS = 1e-6;
const num = (v) => parseFloat(v) || 0;
const over = (Array.isArray(raw) ? raw : raw ? [raw] : []).filter((r) => {
  if (!r || !r.gd_line_id) return false;
  const m = num(mine[String(r.gd_line_id)]);
  const covered = num(r.covered);
  return m > EPS && covered > EPS && covered + m > num(r.gd_qty) + EPS;
});
if (!over.length) return { over: 0, message: "" };
const fmt = (v) => String(Number(num(v).toFixed(8)));
const named = over.slice(0, 3).map((r) => (r.delivery_no || "Goods Delivery") + " " + (r.item_name || "line") + ": " + fmt(r.covered) + " of " + fmt(r.gd_qty) + " already on " + (r.pickings || "another Picking"));
return {
  over: 1,
  message: "Picking not saved: these Goods Delivery lines are already on another Picking. " + named.join("; ") + (over.length > 3 ? "; and " + (over.length - 3) + " more" : "") + ". Refresh the list and convert only what is left.",
};

// This run's key for its cache entries (it used to read the whole arrayData only for created_by).
const unique = `${Date.now()}_${Math.random().toString(36).slice(2, 10)}`;

return {
  unique
};

const currentIndexRaw = {{node:get_cache_node_hGFbHnzQ.data}}
const index = currentIndexRaw ? parseInt(currentIndexRaw, 10) : 0
const saveAs = {{workflowparams:saveAs}}
const pageStatus = {{workflowparams:pageStatus}}
const isForceComplete = {{workflowparams:isForceComplete}}

// The loop's own item: arrayData[index] took every Picking of the batch on every pass.
let data = {{node:loop_BIfi18oK}} || {};
let invalidMessage = "";

// Validation: For saveAs "Completed", at least one item must have picked_qty > 0
if (saveAs === "Completed" && !isForceComplete && isForceComplete !== 1) {
  const hasPickedQty = data.table_picking_items && data.table_picking_items.length > 0 &&
    data.table_picking_items.some(item => item.picked_qty > 0);

  if (!hasPickedQty) {
    invalidMessage = "Cannot complete picking. At least one item must have picked quantity greater than 0.";
  }

  if (data.to_status === "Cancelled") {
    invalidMessage = "Picking is cancelled. Unable to process picking."
  }
}

if (saveAs !== "Cancelled") {
  if (saveAs === "Draft") {
    if (
      data.to_id_type !== -9999 &&
      (!data.to_id ||
        data.to_id === null ||
        data.to_id === "")
    ) {
      data.to_id = "draft";
    }
  } else {
    if (
      data.to_id_type !== -9999 &&
      (!data.to_id ||
        data.to_id === null ||
        data.to_id === "" ||
        data.to_status === "Draft")
    ) {
      data.to_id = "issued";
    }
  }
}

// Cancel of a Created picking: flag to_id so the document number can be reused
if (
  saveAs === "Cancelled" &&
  data.to_status === "Created" &&
  typeof data.to_id === "string" &&
  data.to_id &&
  !data.to_id.endsWith("-Cancelled")
) {
  data.to_id = data.to_id + "-Cancelled";
}

let updatedStatus = {{workflowparams:saveAs}}
if (saveAs === "Completed" && pageStatus === "Add") {
  updatedStatus = "Created"
}

// Interpolated into sql_node_LockGate, and arrayData is caller-supplied.
// Picking ids are snowflake bigints, so digits-only is exact, not a guess;
// "0" matches no row, which fails closed as "under processing".
const lockId = /^[0-9]+$/.test(String(data.id || "")) ? String(data.id) : "0";

return {
  data,
  itemCount: Array.isArray(data.table_picking_items) ? data.table_picking_items.length : 0,
  updatedStatus,
  nextIndex: index + 1,
  invalidMessage,
  lockId,
  isInvalid: invalidMessage === "" ? 0 : 1
}

const rows = {{node:sql_node_LockGate.data}} || [];
const list = Array.isArray(rows) ? rows : [rows];
const row = list[0];

// A crashed run can never release the mutex in-flow, so a lock this old is
// treated as abandoned and taken over.
const STALE_SEC = 900;

// 0 = free, take the lock   1 = held by a live run   2 = already Completed   3 = Cancelled
let lockState = 1;
let staleRecovered = 0;

if (row && row.id) {
  if (row.to_status === "Completed") {
    lockState = 2;
  } else if (row.to_status === "Cancelled") {
    // A device holding a stale copy must not complete a Picking its GD cancel already closed.
    lockState = 3;
  } else if (row.open_job) {
    // a background confirm / force complete (Picking V2) holds it until its job ends, however long that takes
    lockState = 1;
  } else if (Number(row.is_processing) === 1) {
    const age = Number(row.lock_age_sec);
    // A negative or unparseable age means the clock assumption is off; stay
    // locked rather than risk stealing a lock from a run still in progress.
    if (isFinite(age) && age > STALE_SEC) {
      lockState = 0;
      staleRecovered = 1;
    }
  } else {
    lockState = 0;
  }
}

return {
  lockState,
  staleRecovered
}

return {
  required_fields: JSON.stringify([
      { name: "plant_id", label: "Plant" },
      { name: "to_id", label: "Transfer Order No" },
      { name: "ref_doc_type", label: "Reference Document Type" },
      {
        name: "table_picking_items",
        label: "Picking Items",
        isArray: true,
        arrayType: "object",
        arrayFields: [],
      },
]),
  data: JSON.stringify({
    plant_id: {{node:code_node_hjAwTKzF.data.data.plant_id}},
    to_id: {{node:code_node_hjAwTKzF.data.data.to_id}},
    ref_doc_type: {{node:code_node_hjAwTKzF.data.data.ref_doc_type}},
    // CHECK_REQUIRED_FIELD only checks that the list is not empty; a placeholder keeps its verdict.
    table_picking_items: {{node:code_node_hjAwTKzF.data.itemCount}} > 0 ? [{}] : [],
  })
}

let data = {{node:code_node_hjAwTKzF.data.data}} || {}

// 8dp is the maximum configurable column precision, and every Transfer Order Picking
// quantity column is precision 8, so rounding there keeps the client's scale and kills
// float residue (232.85000000000002 -> 232.85).
// NOTE: the maps below are an ALLOW-LIST — any decimal column left out reaches the
// add/update node as a raw float. Add every new decimal column here.
const q8 = (v) => Number((parseFloat(v) || 0).toFixed(8));
// UOM conversion factors, not quantities: a missing/zero factor means "same UOM",
// so they default to 1 rather than 0.
const formatFactor = (value) => {
  const n = parseFloat(value);
  return !n ? 1 : q8(n);
};
// Format qty fields in table_picking_items
if (data.table_picking_items && data.table_picking_items.length > 0) {
  data.table_picking_items = data.table_picking_items.map(item => ({
    ...item,
    qty_to_pick: q8(item.qty_to_pick),
    pending_process_qty: q8(item.pending_process_qty),
    picked_qty: q8(item.picked_qty),
    to_pick_alt: q8(item.to_pick_alt),
    pending_alt: q8(item.pending_alt),
    order_base_qty: formatFactor(item.order_base_qty),
    picking_base_qty: formatFactor(item.picking_base_qty),
    packing_qty: q8(item.packing_qty),
    net_weight: q8(item.net_weight),
  }));
}
// Format qty fields in table_picking_records if exists
if (data.table_picking_records && data.table_picking_records.length > 0) {
  data.table_picking_records = data.table_picking_records.map(item => ({
    ...item,
    qty_to_pick: q8(item.qty_to_pick),
    picked_qty: q8(item.picked_qty),
    store_out_qty: q8(item.store_out_qty),
    picked_qty_alt: q8(item.picked_qty_alt),
  }));
}

return {
  data
}

const pageStatus = {{workflowparams:pageStatus}}

let pickingData = {{node:code_node_hjAwTKzF.data.data}}

if (pageStatus === 'Add') {
  const rawData = {{node:add_node_j6HU6pFP.data}}
  pickingData = rawData[0]
  pickingData.table_picking_items = {{node:search_node_OmBi3hyy.data.data}}
}

return {
  pickingData
}

const pageStatus = {{workflowparams:pageStatus}}

let pickingData = {{node:code_node_hjAwTKzF.data.data}}

if (pageStatus === 'Add') {
  const rawData = {{node:add_node_j6HU6pFP.data}}
  pickingData = rawData[0]
  pickingData.table_picking_items = {{node:search_node_OmBi3hyy.data.data}}
} else {
  pickingData = {{node:get_node_xPyPMAKx.data.data}}
}

const isPickingPlan = pickingData.ref_doc_type === "Picking Plan" ? 1 : 0;

// The two branches above return DIFFERENT shapes. Add reads the SUB-table
// (transfer_order_jz8m9w3h_sub), which comes back FLAT -- a bundle's items are
// already top-level rows. Edit reads the MASTER (Transfer Order Picking), whose
// subform comes back NESTED, so the items hang off the bundle row and the filters
// below saw only that row: the component GD/PP lines never got stamped on a re-save.
// Flattening makes Edit behave like Add. A document with no bundles is unaffected.
const flattenPickingRows = (rows) =>
  (rows || []).flatMap((row) => {
    const { children, ...rest } = row || {};
    return [rest, ...(Array.isArray(children) ? children : [])];
  });

pickingData.table_picking_items = flattenPickingRows(
  pickingData.table_picking_items
);

// One entry per document or line, digits only (sql_node_StampState takes them as text): the per-row lists
// wrote each GD header once per Picking line, 2,096 writes for the 300-GD convert.
const pickingItems = pickingData.table_picking_items.filter((item) => item.line_status !== "Cancelled");
const digits = (v) => (/^[0-9]{1,20}$/.test(String(v == null ? "" : v)) ? String(v) : "");
const csv = (key) => [...new Set(pickingItems.map((item) => digits(item[key])).filter(Boolean))].join(",");

return {
  isPickingPlan,
  gdIdCsv: isPickingPlan ? "" : csv("gd_id"),
  gdLineIdCsv: isPickingPlan ? "" : csv("gd_line_id"),
  toIdCsv: isPickingPlan ? csv("to_id") : "",
  toLineIdCsv: isPickingPlan ? csv("to_line_id") : "",
}

// "Created" goes only on rows still waiting for a Picking. The update-nodes below are keyed on id lists, and an
// id list makes the platform ignore their status filter, so they used to reset In Progress / Completed rows too.
const STAMPABLE = { "Not Created": true, "Cancelled": true, "": true };
const raw = {{node:sql_node_StampState.data}};
const rows = Array.isArray(raw) ? raw : raw ? [raw] : [];
const pick = (kind) => [
  ...new Set(rows.filter((r) => r.kind === kind && STAMPABLE[r.picking_status || ""] === true).map((r) => String(r.id))),
];
const gdIds = pick("gd");
const gdLineIds = pick("gd_line");
const toIds = pick("pp");
const toLineIds = pick("pp_line");

return {
  gdIds,
  gdLineIds,
  toIds,
  toLineIds,
  hasGdIds: gdIds.length > 0 ? 1 : 0,
  hasGdLineIds: gdLineIds.length > 0 ? 1 : 0,
  hasToIds: toIds.length > 0 ? 1 : 0,
  hasToLineIds: toLineIds.length > 0 ? 1 : 0,
};

const pickingData = {{node:code_node_hjAwTKzF.data.data}} || {};
const isCreated = pickingData.to_status === "Created" ? 1 : 0;
const isPickingPlan = pickingData.ref_doc_type === "Picking Plan" ? 1 : 0;
const currentPickingId = pickingData.id;
// table_picking_items is a TREE: an item bundle is ONE row with the items under it
// as `children`. The SOURCE lines that this Picking actually stamped are the items'
// -- the bundle row carries the bundle's own gd_line_id/to_line_id and nothing is
// ever picked against it. Reading the top level alone collected ONLY that row, so
// cancelling left every component line stuck at its picked status (unre-pickable)
// while resetting a line the Picking never touched.
const flattenPickingRows = (rows) =>
  (rows || []).flatMap((row) => {
    const { children, ...rest } = row || {};
    return [rest, ...(Array.isArray(children) ? children : [])];
  });

const isBundleRow = (r) => Boolean(r && r.item_bundle_id) && !r.item_code;

const items = flattenPickingRows(pickingData.table_picking_items).filter(
  (i) => i.line_status !== "Cancelled" && !isBundleRow(i)
);
const uniq = (a) => [...new Set(a.filter((v) => v !== null && v !== undefined && v !== ""))];
const gdIds = isCreated ? uniq(items.map((i) => i.gd_id)) : [];
const gdLineIds = isCreated ? uniq(items.map((i) => i.gd_line_id)) : [];
const toIds = isCreated ? uniq(items.map((i) => i.to_id)) : [];
const toLineIds = isCreated ? uniq(items.map((i) => i.to_line_id)) : [];

return { isCreated, isPickingPlan, currentPickingId, gdIds, gdLineIds, toIds, toLineIds };

const currentPickingId = {{node:code_node_CancelPrep.data.currentPickingId}};
const toIds = {{node:code_node_CancelPrep.data.toIds}};
const toLineIds = {{node:code_node_CancelPrep.data.toLineIds}};
const raw = {{node:search_node_OtherPP.data.data}};
const rows = Array.isArray(raw) ? raw : (raw ? [raw] : []);
const others = rows.filter((r) => r.transfer_order_id !== currentPickingId && r.line_status !== "Cancelled");
const otherHeaders = new Set(others.map((r) => r.to_id));
const otherLines = new Set(others.map((r) => r.to_line_id));
const headersToReset = toIds.filter((id) => !otherHeaders.has(id));
const linesToReset = toLineIds.filter((id) => !otherLines.has(id));

return {
  headersToReset: headersToReset.length ? headersToReset : ["__none__"],
  linesToReset: linesToReset.length ? linesToReset : ["__none__"]
};

const currentPickingId = {{node:code_node_CancelPrep.data.currentPickingId}};
const gdIds = {{node:code_node_CancelPrep.data.gdIds}};
const gdLineIds = {{node:code_node_CancelPrep.data.gdLineIds}};
const raw = {{node:search_node_OtherGD.data.data}};
const rows = Array.isArray(raw) ? raw : (raw ? [raw] : []);
const others = rows.filter((r) => r.transfer_order_id !== currentPickingId && r.line_status !== "Cancelled");
const otherHeaders = new Set(others.map((r) => r.gd_id));
const otherLines = new Set(others.map((r) => r.gd_line_id));
const headersToReset = gdIds.filter((id) => !otherHeaders.has(id));
const linesToReset = gdLineIds.filter((id) => !otherLines.has(id));

return {
  headersToReset: headersToReset.length ? headersToReset : ["__none__"],
  linesToReset: linesToReset.length ? linesToReset : ["__none__"]
};

// The Completed branch stashes the Picking workflow's message so the clamp note
// survives out here. A Draft / Created / Cancelled save never runs that branch,
// so the cache is empty and the plain success line stands.
const cached = [{{node:get_cache_node_PickMsg.data}}][0];

const message =
  typeof cached === "string" && cached.trim() !== ""
    ? cached
    : "Picking processed successfully";

return { message }
